#!/usr/bin/env python3
"""Checks for the static landing in site/ (brainkeep.dev), generated by scripts/build_site.py."""
import hashlib
import html
import importlib.util
import struct
import json
import re
import subprocess
import sys
import unittest
from html.parser import HTMLParser
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
SITE = ROOT / "site"
SRC = ROOT / "site-src"
BUILD = ROOT / "scripts" / "build_site.py"
THEME = ROOT / "panel-ui" / "src" / "theme.css"
FONTS = ROOT / "panel-ui" / "src" / "fonts"
ORIGIN = "https://brainkeep.dev"
PAGES = {"en": (SITE / "index.html", "/"), "es": (SITE / "es" / "index.html", "/es/")}
ALL_PAGES = {**PAGES, "404": (SITE / "404.html", "/404")}
REMOTE = re.compile(r"^(https?:)?//", re.I)


class Page(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.elements = []  # (tag, attrs, depth of enclosing svg)
        self.ids = []
        self.inline_scripts = 0
        self.style_tags = 0
        self.title = ""
        self.data_blocks = []  # JSON-LD text: a data block, not a script the CSP must allow
        self._svg = 0
        self._in_title = False
        self._in_data = False

    def handle_starttag(self, tag, attrs):
        a = dict(attrs)
        self.elements.append((tag, a, self._svg))
        if "id" in a:
            self.ids.append(a["id"])
        if tag == "script" and "src" not in a:
            if a.get("type") == "application/ld+json":
                self._in_data = True
                self.data_blocks.append("")
            else:
                self.inline_scripts += 1
        if tag == "style":
            self.style_tags += 1
        if tag == "svg":
            self._svg += 1
        self._in_title = tag == "title"

    def handle_startendtag(self, tag, attrs):
        self.handle_starttag(tag, attrs)
        if tag == "svg":
            self._svg -= 1

    def handle_endtag(self, tag):
        if tag == "svg":
            self._svg -= 1
        self._in_title = False
        self._in_data = False

    def handle_data(self, data):
        if self._in_title:
            self.title += data
        if self._in_data:
            self.data_blocks[-1] += data

    def find(self, tag, **match):
        out = []
        for t, a, _ in self.elements:
            if t == tag and all(a.get(k) == v for k, v in match.items()):
                out.append(a)
        return out


def parse(path):
    page = Page()
    page.feed(path.read_text(encoding="utf-8"))
    return page


def shape(value):
    if isinstance(value, dict):
        return {k: shape(v) for k, v in value.items()}
    if isinstance(value, list):
        return [shape(v) for v in value]
    return type(value).__name__


def tokens(css):
    return sorted(set(re.findall(r"(--[\w-]+)\s*:\s*([^;]+);", css)))


def panel_tokens():
    text = THEME.read_text(encoding="utf-8")
    return tokens(text.split("*, *::before")[0])


class SiteTests(unittest.TestCase):
    def test_translations_have_the_same_keys(self):
        en = json.loads((SRC / "i18n" / "en.json").read_text(encoding="utf-8"))
        es = json.loads((SRC / "i18n" / "es.json").read_text(encoding="utf-8"))
        self.assertEqual(shape(en), shape(es))

    def test_committed_site_matches_the_generator(self):
        result = subprocess.run([sys.executable, str(BUILD), "--check"], capture_output=True, text=True)
        self.assertEqual(result.returncode, 0, result.stdout + result.stderr)

    def test_pages_have_no_template_markers(self):
        for lang, (path, _) in PAGES.items():
            text = path.read_text(encoding="utf-8")
            for marker in ("{{", "}}", "{%", "%}"):
                self.assertNotIn(marker, text, f"{lang}: {marker}")

    def test_language_metadata(self):
        for lang, (path, url_path) in PAGES.items():
            page = parse(path)
            html = page.find("html")[0]
            self.assertEqual(html.get("lang"), lang)
            self.assertTrue(page.title.strip(), lang)
            self.assertTrue(page.find("meta", name="description")[0].get("content"), lang)
            self.assertEqual(page.find("link", rel="canonical")[0]["href"], ORIGIN + url_path)
            alternates = {a["hreflang"]: a["href"] for a in page.find("link", rel="alternate")}
            self.assertEqual(alternates, {"en": ORIGIN + "/", "es": ORIGIN + "/es/", "x-default": ORIGIN + "/"})
            for prop in ("og:title", "og:description", "og:url", "og:type", "og:locale"):
                self.assertTrue(page.find("meta", property=prop), f"{lang}: {prop}")
            self.assertEqual(page.find("meta", property="og:url")[0]["content"], ORIGIN + url_path)
            switch = [a for a in page.find("a") if a.get("hreflang")]
            self.assertEqual({a["hreflang"]: a["href"] for a in switch}, {"en": "/", "es": "/es/"})
            self.assertEqual([a["hreflang"] for a in switch if a.get("aria-current") == "page"], [lang])

    def test_search_and_share_metadata(self):
        locales = {}
        for lang, (path, url_path) in PAGES.items():
            page = parse(path)
            meta = {a.get("property") or a.get("name"): a.get("content") for a in page.find("meta")}
            self.assertLessEqual(len(meta["description"]), 160, f"{lang}: description is cut in results")
            self.assertLessEqual(len(page.title), 60, f"{lang}: title is cut in results")
            image = meta.get("og:image", "")
            self.assertEqual(image, f"{ORIGIN}/og-{lang}.png", lang)
            data = (SITE / f"og-{lang}.png").read_bytes()
            self.assertEqual(data[:8], b"\x89PNG\r\n\x1a\n", lang)
            self.assertEqual(struct.unpack(">II", data[16:24]), (1200, 630), f"{lang}: share image size")
            self.assertEqual((meta.get("og:image:width"), meta.get("og:image:height")), ("1200", "630"), lang)
            self.assertTrue(meta.get("og:image:alt"), lang)
            self.assertEqual(meta.get("twitter:card"), "summary_large_image", lang)
            locales[lang] = (meta["og:locale"], meta.get("og:locale:alternate"))
            self.assertEqual(len(page.data_blocks), 1, f"{lang}: one JSON-LD block")
            ld = json.loads(page.data_blocks[0])
            self.assertEqual(ld["@context"], "https://schema.org")
            self.assertEqual(ld["@type"], "SoftwareApplication")
            self.assertEqual(ld["name"], "Brainkeep")
            self.assertEqual(ld["url"], ORIGIN + url_path)
            self.assertEqual(ld["inLanguage"], lang)
            for key in ("description", "applicationCategory", "operatingSystem", "license", "softwareVersion", "offers"):
                self.assertTrue(ld.get(key), f"{lang}: JSON-LD {key}")
        self.assertEqual(locales["en"][1], locales["es"][0])
        self.assertEqual(locales["es"][1], locales["en"][0])

    def test_no_remote_resources(self):
        for lang, (path, _) in PAGES.items():
            page = parse(path)
            for tag, attrs, _ in page.elements:
                if tag in ("script", "img", "source", "iframe", "audio", "video", "embed"):
                    self.assertFalse(REMOTE.match(attrs.get("src", "")), f"{lang}: {tag} {attrs}")
                if tag == "link" and attrs.get("rel") not in ("canonical", "alternate"):
                    self.assertFalse(REMOTE.match(attrs.get("href", "")), f"{lang}: link {attrs}")
                if tag in ("iframe", "object", "embed"):
                    self.fail(f"{lang}: {tag} is not allowed")
        for css in (SITE / "assets").glob("*.css"):
            text = css.read_text(encoding="utf-8")
            self.assertNotIn("@import", text, css.name)
            for ref in re.findall(r"url\(\s*['\"]?([^'\")]+)", text):
                self.assertFalse(REMOTE.match(ref), f"{css.name}: {ref}")

    def test_content_security_policy_compatible(self):
        # site/_headers forbids inline scripts and styles.
        for lang, (path, _) in ALL_PAGES.items():
            page = parse(path)
            self.assertEqual(page.inline_scripts, 0, lang)
            self.assertEqual(page.style_tags, 0, lang)
            styled = [(t, a) for t, a, _ in page.elements if "style" in a or any(k.startswith("on") for k in a)]
            self.assertEqual(styled, [], lang)

    def test_images_and_icons_are_labelled_or_hidden(self):
        for lang, (path, _) in PAGES.items():
            page = parse(path)
            for tag, attrs, depth in page.elements:
                if tag == "img":
                    self.assertIn("alt", attrs, f"{lang}: {attrs}")
                if tag == "svg" and depth == 0:
                    labelled = attrs.get("role") == "img" and attrs.get("aria-label")
                    self.assertTrue(attrs.get("aria-hidden") == "true" or labelled, f"{lang}: svg {attrs}")
                if tag == "button":
                    self.assertTrue(attrs.get("aria-label"), f"{lang}: button without aria-label {attrs}")
            self.assertEqual(len(page.ids), len(set(page.ids)), f"{lang}: duplicate ids")

    def test_local_references_exist(self):
        for lang, (path, _) in ALL_PAGES.items():
            page = parse(path)
            ids = set(page.ids)
            for tag, attrs, _ in page.elements:
                for key in ("href", "src"):
                    ref = attrs.get(key)
                    if not ref or REMOTE.match(ref) or ref.startswith("mailto:"):
                        continue
                    if ref.startswith("#"):
                        self.assertIn(ref[1:], ids, f"{lang}: {ref}")
                        continue
                    target = ref.split("#")[0].split("?")[0]
                    file = SITE / target.lstrip("/")
                    if target.endswith("/"):
                        file = file / "index.html"
                    self.assertTrue(file.is_file(), f"{lang}: {ref}")

    def test_assets_are_versioned_by_content(self):
        for lang, (path, _) in PAGES.items():
            page = parse(path)
            refs = [a["href"] for a in page.find("link", rel="stylesheet")] + [a["src"] for a in page.find("script") if "src" in a]
            self.assertTrue(refs, lang)
            for ref in refs:
                name, _, query = ref.partition("?v=")
                digest = hashlib.sha256((SITE / name.lstrip("/")).read_bytes()).hexdigest()[:10]
                self.assertEqual(query, digest, f"{lang}: {ref}")

    def test_design_tokens_and_fonts_come_from_the_panel(self):
        self.assertEqual(tokens((SITE / "assets" / "tokens.css").read_text(encoding="utf-8")), panel_tokens())
        fonts = sorted(FONTS.glob("*.woff2"))
        self.assertTrue(fonts)
        for font in fonts:
            self.assertEqual((SITE / "assets" / "fonts" / font.name).read_bytes(), font.read_bytes(), font.name)

    def test_loop_values_are_not_expanded_again(self):
        spec = importlib.util.spec_from_file_location("build_site", BUILD)
        build = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(build)
        ctx = {"items": [{"t": "{{a}} {{asset:site.css}}"}], "a": "A"}
        out = build.render("{% for x in items %}<i>{{x.t}}</i>{% endfor %}|{{a}}", ctx, {"site.css": "/x"})
        self.assertEqual(out, "<i>{{a}} {{asset:site.css}}</i>|A")

    def test_quick_start_uses_the_installed_binary_and_a_published_version(self):
        cargo = re.search(r'^version\s*=\s*"([^"]+)"', (ROOT / "Cargo.toml").read_text(encoding="utf-8"), re.M).group(1)
        targets = {"macos": "t=brainkeep-$v-aarch64-macos", "linux": "t=brainkeep-$v-$(uname -m)-linux"}
        for lang, (path, _) in PAGES.items():
            text = path.read_text(encoding="utf-8")
            for system, target in targets.items():
                found = re.search(rf'<pre[^>]*id="qs-{system}"[^>]*>(.*?)</pre>', text, re.S)
                self.assertTrue(found, f"{lang}: no quick start for {system}")
                block = html.unescape(re.sub(r"<[^>]+>", "", found.group(1)))
                self.assertNotRegex(block, r"(?m)^brainkeep ", "the binary is not on PATH right after copying it")
                self.assertIn(f"v={cargo};", block)
                self.assertIn(target, block)
                self.assertIn("shasum -a 256 -c", block)
                self.assertEqual(len(re.findall(r"(?m)^# ", block)), 3, f"{lang}/{system}: three commented steps")
                self.assertLessEqual(max(len(line) for line in block.splitlines()), 64, f"{lang}/{system}: long line")
            copy = parse(path).find("button", **{"data-copy": "qs-macos"})
            self.assertTrue(copy, f"{lang}: copy button targets the default system")

    def test_security_headers(self):
        text = (SITE / "_headers").read_text(encoding="utf-8")
        csp = re.search(r"Content-Security-Policy: (.+)", text).group(1)
        self.assertIn("default-src 'self'", csp)
        self.assertIn("script-src 'self' https://static.cloudflareinsights.com", csp)
        self.assertIn("connect-src 'self' https://cloudflareinsights.com", csp)
        self.assertIn("frame-ancestors 'none'", csp)
        self.assertNotIn("unsafe-inline", csp)
        self.assertNotIn("unsafe-eval", csp)
        self.assertIn("object-src 'none'", csp)
        for header in ("Strict-Transport-Security", "X-Content-Type-Options: nosniff", "Referrer-Policy"):
            self.assertIn(header, text)
        self.assertRegex(text, r"/assets/\*\n\s+Cache-Control: public, max-age=31536000, immutable")


if __name__ == "__main__":
    unittest.main(verbosity=1)
